<?php
namespace SignalPilot\AI;use SignalPilot\Contracts\AIProviderInterface;
class OpenAIProvider implements AIProviderInterface{public function evaluateOpportunity(array $m,array $settings,array $strategy=[]):array{$key=$settings['openai_api_key']??''; if($key){$payload=['model'=>$settings['openai_model']??'gpt-4o-mini','messages'=>[['role'=>'system','content'=>'Return compact JSON: action BUY|WAIT|IGNORE, confidence 0-100, entry, stop_loss, take_profit, reward_risk, reason.'],['role'=>'user','content'=>json_encode(['market'=>$m,'strategy'=>$strategy])]],'response_format'=>['type'=>'json_object']];$ch=curl_init('https://api.openai.com/v1/chat/completions');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>20]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);$json=json_decode($raw,true);$content=$json['choices'][0]['message']['content']??'';$d=json_decode($content,true);if($code<300&&is_array($d))return $d+['provider'=>'openai'];}
 $p=(float)$m['price'];$conf=(($m['trend']??'')==='up'&&($m['momentum']??0)>0)?82:55;return ['action'=>$conf>=75?'BUY':'WAIT','confidence'=>$conf,'entry'=>$p,'stop_loss'=>round($p*.98,2),'take_profit'=>round($p*1.04,2),'reward_risk'=>'2.0','reason'=>'Deterministic fallback analysis for paper scanning.','provider'=>'fallback'];}}
